var r=[{title:`S’entraîner par forte chaleur`,text:`La chaleur et l’humidité peuvent rendre une séance facile bien plus difficile. Choisissez les heures fraîches et les parcours à l’ombre, commencez doucement et buvez suffisamment selon les conditions. Les CDC conseillent de s’arrêter et d’aller dans un endroit frais si vous vous sentez faible ou sur le point de vous évanouir. Une confusion, un malaise ou une suspicion de coup de chaleur nécessite des secours d’urgence.`},{title:`Jours froids, humides et venteux`,text:`Portez des couches que vous pouvez retirer et couvrez la peau exposée par temps froid. La pluie et la transpiration peuvent rendre les vêtements et les surfaces dangereusement froids, et un froid intense peut provoquer des gelures ou une hypothermie. La glace ou une mauvaise visibilité sont une bonne raison de vous entraîner à l’intérieur ce jour-là.`},{title:`Vérifiez le terrain`,text:`Repérez les trous, le gravier meuble, les racines, les trottoirs irréguliers, le mauvais éclairage et les traversées de route. Les pentes modifient la charge sur vos muscles et vos articulations. Sur un nouveau parcours, commencez à une allure confortable, évitez les sprints à fond et portez des chaussures avec une bonne adhérence pour la surface.`},{title:`Vérifiez les équipements du parc`,text:`Les bancs, les rampes et les barres de traction peuvent être abîmés par les intempéries, mal fixés ou non conçus pour des exercices dynamiques. Cherchez les arêtes tranchantes, la rouille, les fixations cassées et les supports branlants. Ne vous suspendez à rien qui ne soit clairement conçu pour vous porter. Laissez beaucoup de place aux cyclistes, aux enfants et aux autres usagers du parc.`},{title:`Revérifiez à chaque fois`,text:`Les conditions extérieures changent, alors regardez de nouveau à chaque sortie. Par temps dangereux, passez à une séance en intérieur ou à faible impact, et choisissez des parcours et des mouvements adaptés à la lumière, au sol et à votre expérience.`}];var t=[{label:`CDC : faire de l’exercice par temps chaud`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`},{label:`CDC : prévenir les gelures et l’hypothermie`,url:`https://www.cdc.gov/winter-weather/prevention/preventing-frostbite.html`},{label:`CDC : recommandations d’activité physique pour les adultes`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var a={sections:r,sources:t};export{a as default,r as sections,t as sources};